features=[]
for module,(sources,items) in MODULES.items():
 for name,operation,persona,condition in items:
  features.append({'feature_id':f'FEAT-{len(features)+1:03d}','module':module,'capability':name,'operation_class':operation,'user_roles':persona,'source_dependencies':[s.strip() for s in sources.split(',')],'rule_or_failure_condition':condition,'status':'fixture_supported' if operation in ('read','read_escalate','propose') else 'requires_application_implementation','demo_priority':'P0' if name in ('Ticket creation with idempotency','Cross-tenant API denial','Human approval request','Approved-action execution','VPN session diagnosis','Latest approved policy precedence','Agent tool allowlist','Action payload hash integrity','Timeout-after-commit reconciliation','Agent-to-human handoff') else 'P1'})
(ROOT/'data'/'feature_inventory.json').write_text(json.dumps(features,indent=2)+'\n')
md=['# Feature and Use-Case Coverage','',f'**{len(features)} enterprise capability specifications across {len(MODULES)} modules.**','', 'This is a **scope and data coverage specification**, not a claim that every capability is coded in the mock API. `fixture_supported` means the data supports the capability. `requires_application_implementation` means the application or agent logic must still be built.','']
for module in MODULES:
 md+=['## '+module,'']
 for f in features:
  if f['module']==module:md.append(f"- **{f['feature_id']} {f['capability']}** — {f['operation_class']}; users: {f['user_roles']}; guardrail: {f['rule_or_failure_condition']}")
 md.append('')
(ROOT/'docs'/'FEATURE_MATRIX.md').write_text('\n'.join(md)+'\n')
print(len(features), 'features', len(MODULES), 'modules')
